<template><div class="page-heading"><div><div class="eyebrow">INFRASTRUCTURE</div><h1>系统监控</h1><p>服务健康、系统资源占用、调度器与数据库备份</p></div><el-button :icon="Refresh" @click="load">刷新状态</el-button></div>
  <div v-loading="loading" class="system-wrap"><div class="system-live-strip"><span class="eyebrow">RUNTIME TELEMETRY</span><span><i class="socket-led open"></i>健康检查 {{ stats ? '已更新' : '等待数据' }}</span><span v-if="stats?.updated_at">最后同步 {{ formatDate(stats.updated_at) }}</span></div><div class="system-metrics"><div class="surface sys-card" v-for="item in resourceCards" :key="item.label"><div class="sys-card-head"><span>{{item.label}}</span><el-icon><component :is="item.icon"/></el-icon></div><div class="sys-main">{{item.value}}<small>{{item.unit}}</small></div><el-progress :percentage="Math.min(item.percent,100)" :stroke-width="5" :show-text="false" :color="item.color"/><div class="sys-detail">{{item.detail}}</div></div></div>
  <div class="system-grid"><section class="surface"><div class="surface-head"><div><h3>依赖服务状态</h3><p>运行时健康检查</p></div></div><div class="service-row" v-for="s in services" :key="s.label"><div class="service-led" :class="s.ok?'ok':'bad'"></div><div class="service-label"><b>{{s.label}}</b><small>{{s.detail}}</small></div><el-tag :type="s.ok?'success':'danger'" effect="dark">{{s.ok?'正常':'异常'}}</el-tag></div></section>
  <section class="surface"><div class="surface-head"><div><h3>运行环境</h3><p>应用进程与调度器</p></div></div><div class="runtime-list"><div><span>Python 版本</span><b>{{stats?.python_version||'—'}}</b></div><div><span>运行时长</span><b>{{duration(stats?.uptime_seconds)}}</b></div><div><span>进程运行时长</span><b>{{duration(stats?.process_uptime_seconds)}}</b></div><div><span>任务调度器</span><b>{{stats?.scheduler_running?'运行中':'未运行'}} · {{stats?.scheduler_jobs||0}} 个任务</b></div><div><span>系统负载</span><b>{{stats?.load_average?.join(' / ')||'—'}}</b></div></div></section></div>
  <section class="surface backup-panel"><div class="surface-head"><div><h3>数据库备份</h3><p>将当前数据库备份到服务器持久化目录</p></div><el-button type="primary" :loading="backupLoading" @click="createBackup">立即备份</el-button></div><el-table :data="backups" stripe empty-text="暂无备份文件"><el-table-column prop="name" label="备份文件" min-width="250"/><el-table-column label="文件大小" width="130"><template #default="s">{{s.row.size_mb != null ? `${s.row.size_mb} MB` : formatBytes(s.row.size_bytes)}}</template></el-table-column><el-table-column prop="created_at" label="创建时间" width="185"><template #default="s">{{formatDate(s.row.created_at)}}</template></el-table-column></el-table></section></div>
</template>
<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { Refresh } from '@element-plus/icons-vue'
import { api } from '../api'
const stats=ref<any>(),backups=ref<any[]>([]),loading=ref(false),backupLoading=ref(false)
const resourceCards=computed(()=>[{label:'CPU 使用率',value:stats.value?.cpu_percent??0,unit:'%',percent:stats.value?.cpu_percent??0,detail:`负载 ${stats.value?.load_average?.join(' / ')||'—'}`,icon:'Cpu',color:'#8c79ff'},{label:'内存使用',value:stats.value?.memory_percent??0,unit:'%',percent:stats.value?.memory_percent??0,detail:`${(stats.value?.memory_used_mb/1024||0).toFixed(1)} / ${(stats.value?.memory_total_mb/1024||0).toFixed(1)} GB`,icon:'Coin',color:'#46c7e4'},{label:'磁盘占用',value:stats.value?.disk_percent??0,unit:'%',percent:stats.value?.disk_percent??0,detail:`${stats.value?.disk_used_gb||0} / ${stats.value?.disk_total_gb||0} GB`,icon:'Files',color:'#55d2a1'}])
const services=computed(()=>[{label:'PostgreSQL 数据库',ok:!!stats.value?.db_ok,detail:'业务数据与配置存储'},{label:'Redis 缓存',ok:!stats.value?.redis_enabled||!!stats.value?.redis_ok,detail:stats.value?.redis_enabled?'已启用':'未启用（可选）'},{label:'任务调度器',ok:!!stats.value?.scheduler_running,detail:`${stats.value?.scheduler_jobs||0} 个调度任务已注册`}])
async function load(){loading.value=true;try{const [s,b]=await Promise.all([api.get('/system/stats'),api.get('/system/backups')]);stats.value=s.data;backups.value=Array.isArray(b.data)?b.data:[]}finally{loading.value=false}}
async function createBackup(){backupLoading.value=true;try{const {data}=await api.post('/system/backup');ElMessage.success(data.message||data.detail||'已创建备份');await load()}finally{backupLoading.value=false}}
function duration(seconds:number){if(seconds==null)return '—';const d=Math.floor(seconds/86400),h=Math.floor(seconds%86400/3600),m=Math.floor(seconds%3600/60);return `${d}天 ${h}小时 ${m}分`}
function formatBytes(n:number){if(!n)return '0 B';const u=['B','KB','MB','GB'];let i=0,v=n;while(v>=1024&&i<u.length-1){v/=1024;i++}return `${v.toFixed(1)} ${u[i]}`}
function formatDate(v:string){return v?new Date(v).toLocaleString('zh-CN'):'—'}
onMounted(load)
</script>
<style scoped>.system-wrap{display:flex;flex-direction:column;gap:14px}.system-live-strip{display:flex;align-items:center;gap:16px;padding:8px 12px;border:1px solid #273141;border-radius:8px;background:#111823;color:#8d9ab0;font-size:10px}.system-live-strip .eyebrow{margin:0;color:#9481ff;font-size:9px}.system-live-strip .socket-led{margin-right:5px}.system-metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.sys-card{padding:19px}.sys-card-head{display:flex;justify-content:space-between;color:#9aa6b8;font-size:11px}.sys-card-head .el-icon{font-size:17px;color:#a28eff}.sys-main{font-size:28px;font-weight:600;margin:13px 0}.sys-main small{font-size:12px;color:#9aa6b8;margin-left:4px}.sys-detail{margin-top:9px;color:#79869b;font-size:10px}.system-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.service-row{display:flex;align-items:center;gap:12px;padding:13px 0;border-top:1px solid #273141}.service-led{width:8px;height:8px;border-radius:50%;background:#4bd3a1}.service-led.bad{background:#ed7181}.service-label{flex:1;display:flex;flex-direction:column;gap:4px}.service-label b{font-size:11px}.service-label small{font-size:9px;color:#7c899e}.runtime-list>div{display:flex;justify-content:space-between;padding:10px 0;border-top:1px solid #273141;font-size:10px}.runtime-list span{color:#8793a7}.runtime-list b{font-weight:500;color:#dde4ef}.backup-panel{padding:18px}@media(max-width:800px){.system-grid{grid-template-columns:1fr}}@media(max-width:600px){.system-metrics{grid-template-columns:1fr}.sys-card{padding:15px}.backup-panel{overflow:auto}}</style>
